import { useEffect } from 'react'
import { EditorContent, useEditor, useEditorState, type JSONContent } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'

function PostEditor({ draft, setDraft }: { draft: JSONContent; setDraft: (d: JSONContent) => void }) {
  const editor = useEditor({
    extensions: [StarterKit],
    content: draft,
    immediatelyRender: false,
    onUpdate: ({ editor }) => setDraft(editor.getJSON()),
  })

  // Push outside changes in, without echoing our own edits back.
  useEffect(() => {
    if (!editor || JSON.stringify(editor.getJSON()) === JSON.stringify(draft)) return
    editor.commands.setContent(draft, { emitUpdate: false })
  }, [editor, draft])

  const ui = useEditorState({
    editor,
    selector: ({ editor }) => ({
      bold: editor?.isActive('bold') ?? false,
      words: editor?.getText().split(/\s+/).filter(Boolean).length ?? 0,
    }),
  })

  return (
    <>
      <button
        className={ui?.bold ? 'on' : ''}
        onClick={() => editor?.chain().focus().toggleBold().run()}
      >B</button>
      <EditorContent editor={editor} />
      <p>{ui?.words ?? 0} words</p>
    </>
  )
}

