  onUnmount(() => { binding.dispose(); editor.dispose() })

  return (
    <>
      <button
        class={() => (editor.isActive('bold') ? 'on' : '')}
        onClick={() => editor.chain()?.focus().toggleBold().run()}
      >B</button>
