import { onUnmount } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { CodeEditor, createEditor, useEditorSignal } from '@pyreon/code'

const config = signal({ host: 'localhost', port: 3000 })
const error = signal('')

function ConfigEditor() {
  const editor = createEditor({ language: 'json', theme: 'dark' })
  useEditorSignal({
    editor,
    signal: config,
    serialize: (v) => JSON.stringify(v, null, 2),
    parse: (text) => {
      const next = JSON.parse(text)
      error.set('')
      return next
    },
    onParseError: (e) => error.set(e.message),
  })
  onUnmount(() => editor.dispose()) // CodeEditor does not dispose the instance it is handed

  return (
    <>
      <CodeEditor instance={editor} style="height: 300px" />
      <p role="alert">{error}</p>
    </>
  )
}

