import { onUnmount } from '@pyreon/core'
import { effect, signal } from '@pyreon/reactivity'
import { bindRichTextToSignal, createRichTextEditor, RichText } from '@pyreon/rich-text'

declare function saveDraft(html: string): Promise<void>

const body = signal('<p>Start writing…</p>')

function Composer() {
  const editor = createRichTextEditor({ content: body.peek(), placeholder: 'Write something', ariaLabel: 'Message' })
  const binding = bindRichTextToSignal({ editor, signal: body, format: 'html' })
  let timer: ReturnType<typeof setTimeout> | undefined
  const autosave = effect(() => {
    const html = body()
    clearTimeout(timer)
    timer = setTimeout(() => void saveDraft(html), 1000)
  })
  onUnmount(() => { clearTimeout(timer); autosave.dispose(); binding.dispose(); editor.dispose() })

  return (
    <>
      <RichText instance={editor} style="min-height: 12rem" />
      <footer>
        {() => editor.characterCount()} / 280
        <button disabled={() => !editor.canUndo()} onClick={() => editor.undo()}>Undo</button>
      </footer>
    </>
  )
}

