}

import { signal } from '@pyreon/reactivity'
import { CodeWebView } from '@pyreon/code/webview'
import { RichTextWebView } from '@pyreon/rich-text/webview'

const code = signal('let total = 0')
const note = signal('<p>Hello from the same source</p>')
const failure = signal('')

const Editors = () => (
  <>
    <CodeWebView
      state={() => ({ value: code(), language: 'typescript', readOnly: false })}
      onChange={(v) => code.set(v)}
      onError={(m) => failure.set(m)}
    />
    <RichTextWebView
      state={() => ({ content: note(), editable: true })}
      onChange={(text) => note.set(text)}
      onError={(m) => failure.set(m)}
      grow
    />
  </>
)
